const email = $input.first().json;
return [{
  json: {
    replyToEmail: email.from || null,
    text: (email.text || email.snippet || '').trim(),
    timestamp: new Date(email.date || Date.now()).toISOString()
  }
}];

const fx = $input.first().json;
const agentJson = $('AI Agent').item.json;
const agentRaw = agentJson.output || agentJson.text || '';

let parsed;
try {
  parsed = JSON.parse(agentRaw);
} catch (e) {
  const match = agentRaw.match(/\{[\s\S]*\}/);
  try { parsed = match ? JSON.parse(match[0]) : {}; } catch (e2) { parsed = {}; }
}

const src = $('Code in JavaScript').item.json;
const rate = (fx.rates && fx.rates.GBP) || 1;
const amount = parsed.amount != null ? Number(parsed.amount) : 0;

function uuidv4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

const now = new Date();
const dateParts = String(parsed.date || now.toLocaleDateString('en-GB')).split('/');
const day = parseInt(dateParts[0], 10) || now.getDate();
const month = parseInt(dateParts[1], 10) || (now.getMonth() + 1);
const year = parseInt(dateParts[2], 10) || now.getFullYear();
const txDate = new Date(year, month - 1, day);

const monthNames = ['January','February','March','April','May','June','July','August','September','October','November','December'];

function isoWeek(dt) {
  const target = new Date(dt.valueOf());
  const dayNr = (dt.getDay() + 6) % 7;
  target.setDate(target.getDate() - dayNr + 3);
  const firstThursday = target.valueOf();
  target.setMonth(0, 1);
  if (target.getDay() !== 4) { target.setMonth(0, 1 + ((4 - target.getDay()) + 7) % 7); }
  return 1 + Math.ceil((firstThursday - target) / 604800000);
}

const fyStart = new Date(year, 3, 6);
const fiscalYear = txDate >= fyStart ? (year + '/' + String(year + 1).slice(-2)) : ((year - 1) + '/' + String(year).slice(-2));

const roundedTimestamp = Math.floor(Date.now() / (1000 * 60 * 30));
const dedupHash = [src.replyToEmail, amount, parsed.merchant_or_source, roundedTimestamp].join('|');

return [{
  json: {
    TransactionID: 'txn_' + uuidv4(),
    Type: parsed.type === 'income' ? 'Income' : 'Expense',
    Date: String(day).padStart(2,'0') + '/' + String(month).padStart(2,'0') + '/' + year,
    Time: now.toTimeString().slice(0,5),
    Week: isoWeek(txDate),
    Month: monthNames[month - 1],
    Year: year,
    FiscalYear: fiscalYear,
    Amount: amount,
    Currency: parsed.currency || 'GBP',
    ExchangeRate: rate,
    AmountGBP: Math.round(amount * rate * 100) / 100,
    Category: parsed.category || 'Others',
    Subcategory: parsed.subcategory || '',
    MerchantOrSource: parsed.merchant_or_source || 'Unknown',
    PaymentMethod: parsed.payment_method || 'Unknown',
    Account: parsed.account || '',
    Notes: parsed.notes || '',
    Location: parsed.location || '',
    Channel: 'Email',
    RawMessage: src.text || '',
    Status: 'Confirmed',
    ConfidenceScore: parsed.confidence != null ? parsed.confidence : 0,
    DedupHash: dedupHash,
    CreatedAt: now.toISOString(),
    ExecutionID: $execution.id
  }
}];

